// Tipos básicos
const titulo: string = 'Configurar CI';
const prioridad: number = 2;
const hecha: boolean = false;

// Interface: la "forma" de un objeto
export interface Tarea {
  id: number;
  titulo: string;
  hecha: boolean;
  responsable?: string;                          // ? = opcional
  estado: 'pendiente' | 'en-curso' | 'hecha';    // solo estos valores
}

const tareas: Tarea[] = [];                       // array de Tarea

// Función con tipos en parámetros y resultado
function contarPendientes(lista: Tarea[]): number {
  return lista.filter((t) => !t.hecha).length;
}

// Clase: datos + funciones juntos (los componentes de Angular son clases)
export class Tablero {
  nombre = 'Equipo Plataforma';
  private tareas: Tarea[] = [];

  agregar(tarea: Tarea): void {
    this.tareas.push(tarea);
  }
}

